import {
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  vec3,
  vec4,
  mix,
  smoothstep,
  color,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    Mesh,
    CylinderGeometry,
    OctahedronGeometry,
    PlaneGeometry,
    DirectionalLight,
    PointLight,
    Color,
    DoubleSide,
  } = THREE;

  const group = new Group();
  group.name = config.id ?? 'glass-prism';

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 0.6, hex: '#12121a' },
      { at: 1, hex: '#16161d' },
    ],
  };
  const stops = colors.gradientStops;

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  // ---------- BACKDROP (staged gradient plane) ----------
  const bgTop = new Color(stops[stops.length - 1].hex);
  const bgMid = new Color(stops[1] ? stops[1].hex : stops[0].hex);
  const bgBottom = new Color(stops[0].hex);

  const backdropMat = new MeshBasicNodeMaterial();
  {
    const vy = uv().y;
    const lower = mix(
      vec3(bgBottom.r, bgBottom.g, bgBottom.b),
      vec3(bgMid.r, bgMid.g, bgMid.b),
      smoothstep(float(0.0), float(0.6), vy)
    );
    const grad = mix(
      lower,
      vec3(bgTop.r, bgTop.g, bgTop.b),
      smoothstep(float(0.6), float(1.0), vy)
    );
    backdropMat.colorNode = vec4(grad, float(1.0));
  }
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- GLASS PRISM (triangular via 3-sided cylinder) ----------
  // radius chosen so equilateral side ~1.2: side = radius * sqrt(3) -> radius ~0.7
  const prismGeo = new CylinderGeometry(0.7, 0.7, 1.8, 3, 1);
  const prismMat = new MeshPhysicalNodeMaterial();
  prismMat.transmission = 1.0;
  prismMat.thickness = 0.9;
  prismMat.ior = 1.55;
  prismMat.roughness = 0.08;
  prismMat.metalness = 0.0;
  prismMat.clearcoat = 0.25;
  prismMat.clearcoatRoughness = 0.1;
  prismMat.iridescence = 1.0;
  prismMat.iridescenceIOR = 1.3;
  prismMat.iridescenceThicknessRange = [120, 480];
  prismMat.attenuationColor = new Color(colors.paper);
  prismMat.attenuationDistance = 2.5;
  prismMat.transparent = true;
  // subtle dispersive tint via TSL emissive/color node
  {
    const vy = uv().y;
    const disp = mix(
      vec3(1.0, 0.86, 0.9),
      vec3(0.86, 0.94, 1.0),
      smoothstep(float(0.0), float(1.0), vy)
    );
    prismMat.colorNode = vec4(disp, float(1.0));
  }

  const prism = new Mesh(prismGeo, prismMat);
  // axis horizontal: rotate cylinder (y-axis) to lie along x
  prism.rotation.z = Math.PI / 2 + THREE.MathUtils.degToRad(12);
  prism.rotation.y = THREE.MathUtils.degToRad(20);
  group.add(prism);
  disposables.push(prismGeo, prismMat);

  // ---------- EMISSIVE CORE (octahedron) ----------
  const coreGeo = new OctahedronGeometry(0.35, 0);
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.color = new Color(colors.accent);
  coreMat.emissive = new Color(colors.accent);
  coreMat.emissiveIntensity = 2.2;
  coreMat.roughness = 0.4;
  coreMat.metalness = 0.0;
  const core = new Mesh(coreGeo, coreMat);
  group.add(core);
  disposables.push(coreGeo, coreMat);

  // core glow light (accent, kept low)
  const coreGlow = new PointLight(new Color(colors.accent), 1.0, 4, 2);
  coreGlow.position.set(0, 0, 0);
  group.add(coreGlow);

  // ---------- LIGHTS: back-left cool rim ----------
  const rim = new DirectionalLight(new Color('#9fb0c4'), 1.4);
  rim.position.set(-3, 1.5, -3);
  rim.target.position.set(0, 0, 0);
  group.add(rim);
  group.add(rim.target);

  const keyFill = new DirectionalLight(new Color(colors.paper), 0.9);
  keyFill.position.set(2.5, 2, 3);
  keyFill.target.position.set(0, 0, 0);
  group.add(keyFill);
  group.add(keyFill.target);

  // ---------- CAUSTIC STREAK (floor plane) ----------
  const causticGeo = new PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial();
  causticMat.transparent = true;
  {
    const cRed = new Color(colors.accent);
    const cPaper = new Color(colors.paper);
    const cCool = new Color('#9fb0c4');
    const vx = uv().x;
    const seg1 = mix(
      vec3(cRed.r, cRed.g, cRed.b),
      vec3(cPaper.r, cPaper.g, cPaper.b),
      smoothstep(float(0.2), float(0.5), vx)
    );
    const grad = mix(
      seg1,
      vec3(cCool.r, cCool.g, cCool.b),
      smoothstep(float(0.5), float(0.8), vx)
    );
    causticMat.colorNode = vec4(grad, float(0.35));
  }
  const caustic = new Mesh(causticGeo, causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, 0);
  group.add(caustic);
  disposables.push(causticGeo, causticMat);

  // ---------- TEXT ----------
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjs = [];

  function findText(role, fallback) {
    const it = items.find((i) => i.role === role);
    return it ? it.text : fallback;
  }

  const headlineText = findText('headline', 'Light, machined.');
  const captionText = findText(
    'caption',
    'SAPPHIRE OVER DIAL / ZERO DISTORTION'
  );

  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 68,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: -0.5,
  });
  headline.position.set(0, -1.75, 0.2);
  group.add(headline);
  textObjs.push(headline);

  const caption = ctx.fontAtlas.createText(captionText, {
    fontSize: 18,
    color: '#9fb0c4',
    align: 'center',
    letterSpacingPx: 1.4,
  });
  caption.position.set(0, -2.25, 0.2);
  group.add(caption);
  textObjs.push(caption);

  // ---------- CINEMATIC PRIMITIVES ----------
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      try {
        const handle = fn(prism, p.params ?? {});
        if (handle) primitiveHandles.push(handle);
      } catch (e) {
        /* primitive failed, continue */
      }
    }
  }

  // ---------- ENTRANCE MOTION ----------
  const entrance = gsap.timeline();
  group.scale.set(0.96, 0.96, 0.96);
  entrance.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  entrance.from(
    prism.position,
    { y: 0.35, duration: 0.7, ease: 'power3.out' },
    0
  );
  for (let i = 0; i < textObjs.length; i++) {
    const t = textObjs[i];
    const baseY = t.position.y;
    entrance.fromTo(
      t.position,
      { y: baseY - 0.2 },
      { y: baseY, duration: 0.5, ease: 'power2.out' },
      0.3 + i * 0.08
    );
  }
  timelines.push(entrance);

  // idle breathing of core (single slow transform)
  const idle = gsap.to(core.rotation, {
    y: Math.PI * 2,
    duration: 24,
    ease: 'none',
    repeat: -1,
  });
  timelines.push(idle);

  const coreBreath = gsap.to(coreMat, {
    emissiveIntensity: 1.7,
    duration: 2.4,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1,
  });
  timelines.push(coreBreath);

  // ---------- HOVER HANDLERS ----------
  let hoverTl = null;
  group.userData.handlers = {
    hover: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.to(caustic.scale, {
        x: 1.08,
        duration: 0.35,
        ease: 'power2.out',
      });
    },
    hoverEnd: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.to(caustic.scale, {
        x: 1.0,
        duration: 0.9,
        ease: 'power4.out',
      });
    },
    click: () => {
      ctx.emit?.('navigate', { to: 'hub-collection' });
    },
  };

  // ---------- CLEANUP ----------
  group.userData.cleanup = () => {
    for (const tl of timelines) {
      try {
        tl.kill();
      } catch (e) {}
    }
    if (hoverTl) {
      try {
        hoverTl.kill();
      } catch (e) {}
    }
    for (const h of primitiveHandles) {
      try {
        h.cleanup && h.cleanup();
      } catch (e) {}
    }
    for (const d of disposables) {
      try {
        d.dispose && d.dispose();
      } catch (e) {}
    }
    for (const t of textObjs) {
      t.traverse?.((o) => {
        if (o.geometry) o.geometry.dispose?.();
        if (o.material) {
          const m = o.material;
          if (Array.isArray(m)) m.forEach((mm) => mm.dispose?.());
          else m.dispose?.();
        }
      });
    }
  };

  return group;
}
